const X = 3, R = 3.8, TOP = -0.6, BASE = -16;             // bin centre, half-width, rim and floor of the barrel (m)
machine("OreBin", { id: "silo", at: [X + 8, 0, -20], cut: true });   // the silo model (its barrel sits 8 m off the origin), front half cut away
const ore = "#3b3129";
box({ at: [X, 0, -21.8], size: [3, 2.2, 1.6], color: "#c78a1c" });                         // vibrating feeder under the outlet
box({ at: [X + 5.5, 0, -22], size: [8, 1.4, 0.3], color: "#2b2b2b" });                    // its discharge belt to the flask
const head = machine("Conveyor_20m", { id: "head", at: [-21, 0, 0.6], yaw: 0 });
head.at(0).loop("CV_Belt_Top", 3, { mod: 1 }).loop("CV_Belt_Return", -3, { mod: -1 }).loop("CV_Ore", 3, { mod: 2 });

// The ore piling up: layers appear one after another, narrowing at the top like a heap.
const layers = 14;
for (let i = 0; i < layers; i++) {
  const z = BASE + i * 1.1, w = 2 * R * 0.72;   // square layers inside the round barrel
  const l = box({ id: "fill" + i, at: [X, 0, z], size: [w, w, 1.25], color: ore });
  l.at(0).hide(); l.at(0.6 + i * 0.75).show();
  const cap = box({ id: "cap" + i, at: [X, 0, z + 1.2], size: [w * 0.55, w * 0.55, 0.9], color: "#46392e" });   // heap crest
  cap.at(0).hide(); cap.at(0.6 + i * 0.75).show(); if (i < layers - 1) cap.at(0.6 + (i + 1) * 0.75).hide();
}
// Rock falling off the head pulley onto the heap, all the time.
for (let k = 0; k < 9; k++) {
  const r = box({ id: "rock" + k, at: [-1, 0, 1.6], size: [0.45, 0.4, 0.35], color: "#7a6a58", yaw: k * 40 });
  r.at(0).hide();
  for (let t = k * 0.3; t < 11.6; t += 2.7) {
    const fillTop = BASE + Math.min(layers, 1 + (t + 1) / 0.75) * 1.1 + 0.6;
    r.at(t).place([-1, (k % 3 - 1) * 0.5, 1.6]).show()
      .path([[-1, (k % 3 - 1) * 0.5, 1.6], [1.2, (k % 3 - 1) * 0.6, 0.4], [X - 0.5 + (k % 4) * 0.4, (k % 3 - 1) * 0.9, fillTop]], { speed: 9 })
      .hide();
  }
}
light({ at: [X, -10, -4], intensity: 260 }); light({ at: [X, -8, -18], intensity: 200 }); light({ at: [-6, -4, 4], intensity: 90 });
camera.at(0).set([X - 4, -20, 2], [X, 0, -4])
  .fly([X + 2, -22, -14], [X, 0, -16], { over: 12 });
caption(0.5, 5.5, "The silo at the production sub-shaft, cut away: the belt fills it");
caption(6, 11.5, "A feeder draws ore from the bottom; the silo absorbs stoppages so hoisting never waits");
